<?php
require_once dirname(__DIR__).'/includes/features.php';admin_require();$errors=[];$notice=take_flash('case_notice');
$id=filter_var($_GET['id']??$_POST['id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$values=['status'=>'draft'];$existing=null;
try{if($id){$q=db()->prepare('SELECT * FROM case_studies WHERE id=?');$q->execute([$id]);$existing=$q->fetch();if(!$existing)throw new InvalidArgumentException('Case study not found.');$values=$existing;}}catch(Throwable $e){$errors['_form']='Case-study storage is unavailable or this record does not exist.';}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{admin_csrf();[$values,$errors]=validate_case($_POST);$image=$existing['image_path']??'';
  if(($_FILES['case_image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$image=case_upload($_FILES['case_image']);
  if($image!==''&&$values['image_alt']==='')$errors['image_alt']='Describe the screenshot for visitors using assistive technology.';
  if($values['status']==='published'&&$image===''&&$values['project_url']==='')$errors['project_url']='Add a real project URL or an approved screenshot before publishing.';
  if(!$errors){
   $fields=['slug','title','summary','client_name','challenge','solution','outcome','project_url','image_alt','status','evidence_approved'];$params=array_map(static fn($key)=>$values[$key],$fields);$params[]=$image;
   if($id){if(!$existing)throw new InvalidArgumentException('Case study not found.');$params[]=gmdate('Y-m-d H:i:s');$params[]=$id;db()->prepare('UPDATE case_studies SET '.implode(',',array_map(static fn($key)=>$key.'=?',$fields)).',image_path=?,updated_at=? WHERE id=?')->execute($params);}
   else{db()->prepare('INSERT INTO case_studies ('.implode(',',$fields).',image_path) VALUES ('.implode(',',array_fill(0,count($params),'?')).')')->execute($params);$id=(int)db()->lastInsertId();}
   flash('case_notice',$values['status']==='published'?'Case study published.':'Draft saved. It is not visible publicly.');redirect('admin/cases.php?id='.$id);
  }
 }catch(Throwable $e){$errors['_form']=$e instanceof InvalidArgumentException?$e->getMessage():'The case study could not be saved. Check storage and ensure the slug is unique.';}
}
try{$cases=db()->query('SELECT id,title,slug,status FROM case_studies ORDER BY id DESC')->fetchAll();}catch(Throwable $e){$cases=[];$errors['_form']='Import database/features.sql and configure the database to use case studies.';}
page_start('admin',''); ?>
<section class="section"><div class="container"><h1>Case studies</h1><?php admin_navigation();errors_summary($errors); ?><?php if($notice): ?><p class="notice" role="status"><?= e($notice) ?></p><?php endif; ?><p>Publish only real work and approved evidence. Leave entries in draft until you can support the claims. The existing public concepts remain separate.</p><div class="content-layout"><form class="form-card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$id ?>"><h2><?= $id?'Edit case study':'Create a draft' ?></h2><p class="note">Drafts need only a title and slug. Publishing also requires the summary, challenge, solution, outcome, publication approval, and a project URL or screenshot.</p><div class="form-grid"><?php foreach(['title'=>'Project title','slug'=>'URL slug','summary'=>'Short summary','client_name'=>'Client or organisation (only if approved)','project_url'=>'Project URL','image_alt'=>'Screenshot description'] as $name=>$label)field($name,$label,'text',$values,$errors,in_array($name,['title','slug'],true));foreach(['challenge'=>'The real challenge','solution'=>'What Semraa delivered','outcome'=>'Verified outcome or observed result'] as $name=>$label)field($name,$label,'textarea',$values,$errors); ?></div><div class="field"><label for="case-image">Approved screenshot (optional)</label><input type="file" id="case-image" name="case_image" accept="image/jpeg,image/png,image/webp"><p class="note">JPEG, PNG or WebP; under 4 MB and 3000 × 3000 pixels. Uploads are re-encoded as JPEG. Use only images you have permission to publish.</p></div><?php if(!empty($existing['image_path'])): ?><img class="case-image-preview" src="<?= e(url($existing['image_path'])) ?>" alt="<?= e($existing['image_alt']) ?>"><?php endif; ?><?php field('status','Publication status','select',$values,$errors,true,['draft'=>'Draft','published'=>'Published']); ?><label class="approval-choice"><input type="checkbox" name="evidence_approved" value="1" <?= !empty($values['evidence_approved'])?'checked':'' ?>>I confirm this is real work, all claims are accurate, and the content and images are approved for publication.</label><?php if(isset($errors['evidence_approved'])): ?><p class="field-error"><?= e($errors['evidence_approved']) ?></p><?php endif; ?><div class="actions"><button class="button">Save case study</button></div></form><aside><h2>Saved entries</h2><a class="text-link" href="<?= e(url('admin/cases.php')) ?>">Create another draft</a><ul class="case-admin-list"><?php foreach($cases as $case): ?><li><a href="<?= e(url('admin/cases.php?id='.(int)$case['id'])) ?>"><?= e($case['title']) ?></a><span><?= e($case['status']) ?></span><?php if($case['status']==='published'): ?><a class="text-link" href="<?= e(url('case-studies/'.$case['slug'])) ?>">View published page</a><?php endif; ?></li><?php endforeach; ?></ul><?php if(!$cases&&!$errors): ?><p>No case studies yet. Nothing has been invented or published.</p><?php endif; ?></aside></div></div></section><?php page_end(); ?>
